<#
.SYNOPSIS
    Hunt Console -- Windows installer

.DESCRIPTION
    Self-contained installer: the source package is embedded below as a
    base64-encoded zip payload, so this single file is everything needed
    to install.

    Recommended: double-click install-windows.cmd instead of this file
    directly -- it launches this script with the correct execution policy
    bypass for this one run only (nothing is changed system-wide). If you
    prefer to run this .ps1 directly:

        powershell -ExecutionPolicy Bypass -File install-windows.ps1

    What this does:
      1. Checks for Python 3.10+ on PATH (via the 'py' launcher or 'python')
      2. Extracts the embedded source to a temp directory
      3. Creates a virtual environment at -Prefix (default: %USERPROFILE%\.huntconsole)
      4. Installs the package into it (core tool: zero third-party deps)
      5. Adds a huntconsole.bat launcher to %USERPROFILE%\bin

    Nothing here requires Administrator. By default, pip installs with
    normal build isolation, which needs internet access the first time to
    fetch setuptools/wheel if not already cached -- this is standard `pip
    install` behavior, no different from installing any other Python
    package from source. Use -Offline if you are on an air-gapped machine
    that already has setuptools/wheel available system-wide.

.PARAMETER Prefix
    Install location. Default: $env:USERPROFILE\.huntconsole

.PARAMETER WithConnectors
    Also install requests/msal, needed only for the live 'alert' command.

.PARAMETER Offline
    Skip pip's build isolation (--no-build-isolation) and rely on
    setuptools/wheel already being present (e.g. via -SystemSitePackages
    or a pre-provisioned environment). Use only if you know pip cannot
    reach the internet on this machine.
#>

param(
    [string]$Prefix = "$env:USERPROFILE\.huntconsole",
    [switch]$WithConnectors,
    [switch]$Offline
)

$ErrorActionPreference = "Stop"

Write-Host "== Hunt Console installer =="

function Find-Python {
    $candidates = @()
    if (Get-Command py -ErrorAction SilentlyContinue) {
        foreach ($v in @("3.13","3.12","3.11","3.10")) {
            $candidates += [PSCustomObject]@{ Cmd = "py"; Args = @("-$v") }
        }
        $candidates += [PSCustomObject]@{ Cmd = "py"; Args = @() }
    }
    if (Get-Command python -ErrorAction SilentlyContinue) {
        $candidates += [PSCustomObject]@{ Cmd = "python"; Args = @() }
    }
    if (Get-Command python3 -ErrorAction SilentlyContinue) {
        $candidates += [PSCustomObject]@{ Cmd = "python3"; Args = @() }
    }

    foreach ($c in $candidates) {
        try {
            $checkArgs = @($c.Args) + @("-c", "import sys; print(str(sys.version_info[0])+'.'+str(sys.version_info[1]))")
            $verOutput = & $c.Cmd @checkArgs 2>$null
            if ($LASTEXITCODE -eq 0 -and $verOutput) {
                $parts = ([string]$verOutput).Trim().Split(".")
                if ($parts.Length -ge 2 -and [int]$parts[0] -eq 3 -and [int]$parts[1] -ge 10) {
                    return $c
                }
            }
        } catch {
            # This candidate isn't usable (missing, wrong version, or a
            # Microsoft Store app-execution-alias stub) -- try the next one.
            continue
        }
    }
    return $null
}

$py = Find-Python
if (-not $py) {
    Write-Host ""
    Write-Host "ERROR: Python 3.10+ not found on PATH (checked the 'py' launcher, 'python', and 'python3')." -ForegroundColor Red
    Write-Host "Install Python 3.10 or newer from https://python.org (check 'Add python.exe to PATH' during setup) and re-run this installer." -ForegroundColor Red
    exit 1
}
$checkArgs = @($py.Args) + @("--version")
$pyVersionString = & $py.Cmd @checkArgs
Write-Host "Using $pyVersionString ($($py.Cmd) $($py.Args -join ' '))"

$workDir = Join-Path $env:TEMP ("huntconsole-install-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $workDir | Out-Null

try {
    Write-Host "Extracting embedded package..."
    $scriptContent = Get-Content -Path $PSCommandPath -Raw
    $marker = "##__PAYLOAD_BELOW__##"
    # LastIndexOf, not IndexOf: the marker text also appears earlier in
    # this script's own source (in the line that defines $marker above),
    # so IndexOf would find that occurrence instead of the real payload
    # boundary and corrupt every install. LastIndexOf finds the actual
    # boundary right before the base64 data at the end of the file.
    $markerIndex = $scriptContent.LastIndexOf($marker)
    if ($markerIndex -lt 0) {
        Write-Host "ERROR: embedded payload marker not found -- this installer file may be corrupted or truncated." -ForegroundColor Red
        exit 1
    }
    $payloadB64 = $scriptContent.Substring($markerIndex + $marker.Length).Trim()
    $zipBytes = [Convert]::FromBase64String($payloadB64)
    $zipPath = Join-Path $workDir "payload.zip"
    [IO.File]::WriteAllBytes($zipPath, $zipBytes)
    Expand-Archive -Path $zipPath -DestinationPath $workDir -Force

    Write-Host "Creating virtual environment at $Prefix ..."
    $venvArgs = @($py.Args) + @("-m", "venv", "--system-site-packages", "--clear", $Prefix)
    & $py.Cmd @venvArgs
    if ($LASTEXITCODE -ne 0) { throw "venv creation failed (exit code $LASTEXITCODE)" }

    $venvPip = Join-Path $Prefix "Scripts\pip.exe"
    if (-not (Test-Path $venvPip)) { throw "expected pip at $venvPip but it was not created -- venv setup may have failed silently" }

    Write-Host "Installing Hunt Console..."
    if ($Offline) {
        & $venvPip install --quiet --no-build-isolation $workDir
    } else {
        & $venvPip install --quiet $workDir
    }
    if ($LASTEXITCODE -ne 0) {
        throw "pip install failed (exit code $LASTEXITCODE). If this machine has no internet access, re-run with -Offline (requires setuptools/wheel already available system-wide)."
    }

    if ($WithConnectors) {
        & $venvPip install --quiet "requests>=2.31" "msal>=1.28"
        if ($LASTEXITCODE -ne 0) {
            Write-Host "WARNING: could not install requests/msal (no network?) -- core tool still works, the live 'alert' command will not." -ForegroundColor Yellow
        }
    }

    $binDir = Join-Path $env:USERPROFILE "bin"
    if (-not (Test-Path $binDir)) { New-Item -ItemType Directory -Path $binDir | Out-Null }
    $launcherPath = Join-Path $binDir "huntconsole.bat"
    $venvHuntConsole = Join-Path $Prefix "Scripts\huntconsole.exe"
    $batchContent = "@echo off`r`n`"$venvHuntConsole`" %*`r`n"
    Set-Content -Path $launcherPath -Value $batchContent -Encoding ASCII -NoNewline

    Write-Host ""
    Write-Host "== Installed =="
    Write-Host "  huntconsole -> $venvHuntConsole"
    Write-Host "  launcher created at $launcherPath"

    $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
    if ($null -eq $userPath) { $userPath = "" }
    if ($userPath -notlike "*$binDir*") {
        Write-Host ""
        Write-Host "  $binDir is not on your PATH. Add it permanently with:"
        Write-Host "    [Environment]::SetEnvironmentVariable('Path', `$env:Path + ';$binDir', 'User')"
        Write-Host "  then open a new terminal window."
    }
    Write-Host ""
    Write-Host "Try it (current session, full path -- works even before PATH is updated):"
    Write-Host "  & `"$launcherPath`" --help"
    Write-Host ""
}
catch {
    Write-Host ""
    Write-Host "Installation failed: $($_.Exception.Message)" -ForegroundColor Red
    Remove-Item -Recurse -Force $workDir -ErrorAction SilentlyContinue
    exit 1
}

Remove-Item -Recurse -Force $workDir -ErrorAction SilentlyContinue
exit 0

##__PAYLOAD_BELOW__##
